from starkware.cairo.common.memcpy import memcpy

// Simple program that outputs a list of integers. Used for tests.
//
// Hint arguments:
// program_input - Contains a list of integers to output.
func main{output_ptr: felt*}() {
    %{ output = program_input["output"] %}

    // Write output to output_ptr.
    %{ segments.write_arg(ids.output_ptr, output) %}

    // Increment output_ptr.
    tempvar output_len = nondet %{ len(output) %};
    let output_ptr = output_ptr + output_len;
    return ();
}
